Lemma length_firstn_skipn : forall {X} (l : list X) len count, 0 <= len <= Z.of_nat (length l) -> 0 <= count ->
  Z.of_nat (length (firstn (Z.to_nat count) (skipn (Z.to_nat len) l))) = Z.min count (Z.of_nat (length l) - len).
